using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ENC.Encuestas;using GraphApi.Services.ENC.Encuestas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ENC.Encuestas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Encuestas: creación, actualización y eliminación.")]    public class EncuestasMutation    {        [Authorize]        [GraphQLName("createEncuestas")]        [GraphQLDescription("Crea un nuevo Encuesta usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadEncuestas> CreateEncuestasAsync(            [GraphQLDescription("Datos necesarios para crear el Encuesta.")]            clCreateEncuestas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Encuesta.")]            IEncuestasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateEncuestas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateEncuestas")]        [GraphQLDescription("Actualiza los campos especificados de un Encuesta existente.")]        public async Task<clReadEncuestas?> UpdateEncuestasAsync(            [GraphQLDescription("Datos del Encuesta a actualizar.")]            clUpdateEncuestas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Encuesta.")]            IEncuestasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateEncuestas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteEncuestas")]        [GraphQLDescription("Elimina un Encuesta por su ID.")]        public async Task<bool> delEncuestasAsync(            [GraphQLDescription("ID del Encuesta a eliminar.")]            int nEncuestasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Encuesta.")]            IEncuestasService objService        )        {            return await objService.DeleteEncuestas(nEncuestasID);        }    }}